          { label: "Black / African American", pct: 37.06, color: "#4e9e68" },
          { label: "White", pct: 27.31, color: "#2563eb" },
          { label: "Hispanic / Latino", pct: 20.1, color: "#f59e0b" },
          { label: "Asian", pct: 10.37, color: "#ef4444" }
